        d = la.norm(c[i]-c[j])
        if d < mind and not bonded(i,j):
            mind=d; pair=(i,j)
print("min non-bonded:", round(mind,2), pair, syms[pair[0]], syms[pair[1]])

from collections import Counter
print(Counter(syms))
